14370:     // now we should trigger a dedent
14371:     char *dest = PyMem_Malloc(src_len);
14372:     if (!dest) {
14373:         PyErr_NoMemory();
14374:         return NULL;
14375:     }
14376:     char *dest_iter = dest;
14377: 
14378:     for (const char *iter = src; iter < end; ++iter) {
14379:         const char *line_start = iter;
14380:         bool in_leading_space = true;
14381: 
14382:         // iterate over a line to find the end of a line
14383:         while (iter < end && *iter != '\n') {
14384:             if (in_leading_space && *iter != ' ' && *iter != '\t') {
14385:                 in_leading_space = false;
14386:             }
